// ============================================================
// Validate & Parse — C1 HSCH Linguistic Processor
// ============================================================
// يتحقق من صحة البيانات الواردة من الـ AI Agent:
//   1. وجود _____ في النص الألماني
//   2. تطابق عدد الفراغات في النصين (إذا الترجمة يدوية)
// ============================================================

const raw = $input.item.json;

// تطبيع المدخلات
const text_de = String(raw.text_de || '').trim();
let text_ar = String(raw.text_ar || '').trim();
const section = Number(raw.section || 0);
const section_name = String(raw.section_name || '').trim();
const model = Number(raw.model || 0);
const model_name = String(raw.model_name || '').trim();
const slug = String(raw.slug || '').trim().toLowerCase().replace(/\s+/g, '-');
const chatId = String(raw.chatId || '');
const firstName = String(raw.firstName || 'صديقي');

// تطبيع الخيارات (قد تصل كـ string أو array)
let options = raw.options;
if (typeof options === 'string') {
  try { options = JSON.parse(options); } catch(e) { options = []; }
}
if (!Array.isArray(options)) options = [];

// تطبيع الإجابات (قد تصل كـ string أو array)
let answers = raw.answers;
if (typeof answers === 'string') {
  try { answers = JSON.parse(answers); } catch(e) {
    // صيغة: "f,e,b,h"
    answers = answers.split(',').map(a => a.trim()).filter(Boolean);
  }
}
if (!Array.isArray(answers)) answers = [];

// --- التحقق 1: وجود _____ في النص الألماني ---
const blanksDE = (text_de.match(/_____/g) || []).length;
if (blanksDE === 0) {
  return [{ json: {
    valid: false,
    errorMsg: 'صديقي، النص الألماني لا يحتوي على فراغات! يجب تمثيل كل فراغ بـ _____ (خمس شرطات سفلية متتالية بالضبط). يرجى إعادة إرسال النص مع الفراغات.',
    text_de, text_ar, options, answers, section, section_name, model, model_name, slug, chatId, firstName
  } }];
}

// --- التحقق 2: تطابق الفراغات (إذا ترجمة يدوية) ---
const needsTranslation = text_ar.toLowerCase() === 'auto' || text_ar === '';
if (!needsTranslation && text_ar !== '') {
  const blanksAR = (text_ar.match(/_____/g) || []).length;
  if (blanksAR !== blanksDE) {
    return [{ json: {
      valid: false,
      errorMsg: `صديقي، عدد الفراغات في الترجمة العربية (${blanksAR}) لا يساوي عدد الفراغات في النص الألماني (${blanksDE}). يرجى مراجعة الترجمة والتأكد من وجود _____ في نفس المواضع.`,
      text_de, text_ar, options, answers, section, section_name, model, model_name, slug, chatId, firstName
    } }];
  }
}

// --- كل شيء صحيح، نُكمل ---
return [{ json: {
  valid: true,
  needsTranslation,
  text_de,
  text_ar,
  options,
  answers,
  section,
  section_name,
  model,
  model_name,
  slug,
  blanksCount: blanksDE,
  chatId,
  firstName
} }];

// استخراج نص الترجمة من استجابة Lara Translation API
// ودمجها مع بيانات الامتحان الأصلية
// Lara API يُرجع: { translation: '...', detectedLanguage: '...' }

const laraResponse = $input.item.json;

// استخراج النص المترجم من استجابة Lara
let translatedText = '';
if (laraResponse.translation) {
  // استجابة Lara الناجحة
  translatedText = String(laraResponse.translation).trim();
} else if (laraResponse.error || laraResponse.message) {
  // فشلت الترجمة — نُعيد النص الألماني كـ fallback مع تحذير
  const originalData = $('IF Translation Needed').item.json;
  console.log('Lara API Error:', laraResponse.error || laraResponse.message);
  return [{ json: {
    ...originalData,
    text_ar: originalData.text_de,
    translationNote: 'فشلت الترجمة التلقائية عبر Lara: ' + (laraResponse.error || laraResponse.message)
  } }];
}

// الحصول على البيانات الأصلية
const originalData = $('IF Translation Needed').item.json;

// التحقق من تطابق عدد الفراغات
const blanksDE = (originalData.text_de.match(/_____/g) || []).length;
const blanksAR = (translatedText.match(/_____/g) || []).length;

if (blanksDE !== blanksAR) {
  console.log(`Warning: blanks mismatch — DE: ${blanksDE}, AR translated: ${blanksAR}`);
}

return [{ json: {
  ...originalData,
  text_ar: translatedText,
  translationNote: blanksDE !== blanksAR
    ? `تحذير: عدد الفراغات في الترجمة التلقائية (${blanksAR}) يختلف عن الأصل (${blanksDE})`
    : null
} }];

// عقدة التمرير — تستقبل من:
//   - IF Translation Needed [FALSE] (ترجمة يدوية)
//   - Parse Translation Result (ترجمة تلقائية)
// تُجهز بيانات الخيارات لطلب LLM الكلمات المفتاحية

const data = $input.item.json;
const options = Array.isArray(data.options) ? data.options : [];

// تهيئة نص الخيارات للـ LLM
const optionsText = options.map(o => {
  const arPart = o.ar ? ` | العربية: ${o.ar}` : '';
  return `${o.key}) الألمانية: ${o.de}${arPart}`;
}).join('\n');

return [{ json: {
  ...data,
  options_text_for_llm: optionsText
} }];

// استخراج الكلمات المفتاحية من استجابة Basic LLM Chain
// Basic LLM Chain يُرجع: { text: '...' } (بدل choices[0].message.content)
// وبناء مصفوفة الخيارات المُخصَّبة النهائية

const llmResponse = $input.item.json;
// الحصول على بيانات ما قبل الـ LLM من عقدة Set Keywords
const originalData = $('Set Keywords Prompt').item.json;

// استخراج محتوى الاستجابة
// Basic LLM Chain → $json.text
// OpenAI Node → $json.choices[0].message.content
// Fallback → $json.content
let content = '';
if (llmResponse.text) {
  // Basic LLM Chain format
  content = String(llmResponse.text).trim();
} else if (llmResponse.choices && llmResponse.choices[0]) {
  content = llmResponse.choices[0].message.content.trim();
} else if (llmResponse.content) {
  content = String(llmResponse.content).trim();
}

// تنظيف الـ JSON من أي markdown
const cleaned = content
  .replace(/```json\s*/g, '')
  .replace(/```\s*/g, '')
  .trim();

// محاولة تحليل الـ JSON
let keywordsData = [];
try {
  const parsed = JSON.parse(cleaned);
  if (Array.isArray(parsed)) {
    keywordsData = parsed;
  } else if (parsed && typeof parsed === 'object') {
    keywordsData = Object.values(parsed);
  }
} catch(e) {
  console.log('Keywords parsing failed:', e.message);
  keywordsData = [];
}

// إثراء الخيارات بالكلمات المفتاحية
const enrichedOptions = (originalData.options || []).map(opt => {
  const kwMatch = keywordsData.find(k => k && String(k.key).toLowerCase() === String(opt.key).toLowerCase());
  return {
    key: String(opt.key || '').toLowerCase(),
    de: String(opt.de || ''),
    ar: String(opt.ar || ''),
    keywords: {
      de: kwMatch ? String(kwMatch.de_keywords || '') : '',
      ar: kwMatch ? String(kwMatch.ar_keywords || '') : ''
    }
  };
});

return [{ json: {
  text_de: originalData.text_de,
  text_ar: originalData.text_ar,
  options_enriched: enrichedOptions,
  answers: originalData.answers,
  section: originalData.section,
  section_name: originalData.section_name,
  model: originalData.model,
  model_name: originalData.model_name,
  slug: originalData.slug,
  blanksCount: originalData.blanksCount,
  chatId: originalData.chatId,
  firstName: originalData.firstName,
  translationNote: originalData.translationNote || null
} }];

// تهيئة الاستجابة النهائية للـ AI Agent في Main WF
// نُعيد نتيجة واضحة يستخدمها الـ Agent لإعلام المستخدم

const result = $input.item.json;

if (!result.success) {
  return [{ json: {
    output: result.errorMessage || 'حدث خطأ غير متوقع أثناء الرفع على GitHub. تم إبلاغ المشرف.',
    success: false
  } }];
}

// بناء رسالة النجاح للمستخدم
const msg = [
  '🚀 *تم الرفع بنجاح على GitHub!*',
  '',
  `✅ *الملف:* \`${result.filename}\``,
  `📂 *المسار:* \`${result.filePath}\``,
  `📝 *النموذج:* ${result.model_name}`,
  `🔢 *الفراغات:* ${result.totalBlanks}`,
  `🔤 *الخيارات:* ${result.optionsCount}`,
  '',
  'أرسل /new لإضافة نموذج جديد 🎉'
].join('\n');

return [{ json: {
  output: msg,
  success: true,
  filename: result.filename,
  filePath: result.filePath,
  totalBlanks: result.totalBlanks,
  optionsCount: result.optionsCount,
  commitUrl: result.commitUrl
} }];

// تهيئة رسالة خطأ التحقق لإعادتها للـ AI Agent
// الـ Agent سيُرسلها للمستخدم بأسلوبه الودود

const data = $input.item.json;

return [{ json: {
  output: data.errorMsg || 'حدث خطأ في التحقق من البيانات. يرجى مراجعة المدخلات.',
  success: false,
  errorType: 'validation'
} }];
